func newImportRow() unsafe.Pointer { return unsafe.Pointer(new(fuelpurchase.ImportRow)) }

func newNImportRow(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]fuelpurchase.ImportRow, n)))
}

func ptrImportRow(p unsafe.Pointer, c int32) any {
	r := (*fuelpurchase.ImportRow)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ImportBatchID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.RowNumber))
	case 5:
		return &r.Cells
	case 6:
		return &r.Parsed
	case 7:
		return &r.TransactionReference
	case 8:
		return (*string)(unsafe.Pointer(&r.Status))
	case 9:
		return &r.Error
	case 10:
		return (**string)(unsafe.Pointer(&r.ResolvedTractorID))
	case 11:
		return (**string)(unsafe.Pointer(&r.ResolvedFuelCardID))
	case 12:
		return (**string)(unsafe.Pointer(&r.ResolvedJurisdictionID))
	case 13:
		return &r.ResolutionNotes
	case 14:
		return (**string)(unsafe.Pointer(&r.FuelPurchaseID))
	case 15:
		return &r.CreatedAt
	}
	return nil
}

func valueImportRow(p unsafe.Pointer, c int32) any {
	r := (*fuelpurchase.ImportRow)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ImportBatchID)
	case 4:
		return int64(r.RowNumber)
	case 5:
		if r.Cells == nil {
			return nil
		}
		return r.Cells
	case 6:
		if r.Parsed == nil {
			return nil
		}
		return *r.Parsed
	case 7:
		if r.TransactionReference == "" {
			return nil
		}
		return r.TransactionReference
	case 8:
		return string(r.Status)
	case 9:
		if r.Error == "" {
			return nil
		}
		return r.Error
	case 10:
		if r.ResolvedTractorID == nil {
			return nil
		}
		return string(*r.ResolvedTractorID)
	case 11:
		if r.ResolvedFuelCardID == nil {
			return nil
		}
		return string(*r.ResolvedFuelCardID)
	case 12:
		if r.ResolvedJurisdictionID == nil {
			return nil
		}
		return string(*r.ResolvedJurisdictionID)
	case 13:
		if r.ResolutionNotes == nil {
			return nil
		}
		return r.ResolutionNotes
	case 14:
		if r.FuelPurchaseID == nil {
			return nil
		}
		return string(*r.FuelPurchaseID)
	case 15:
		return r.CreatedAt
	}
	return nil
}

func attachImportRow(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*fuelpurchase.ImportRow)(p)
	switch rel {
	case 0:
		r.Batch = (*fuelpurchase.ImportBatch)(child)
	case 1:
		r.FuelPurchase = (*fuelpurchase.FuelPurchase)(child)
	}
}

func beforeCreateImportRow(ctx context.Context, p unsafe.Pointer) error {
	return (*fuelpurchase.ImportRow)(p).BeforeCreate(ctx)
}

func init() {
	fuelCardsTable.Relations[0].Target = workerdb.WorkersSchema()
	fuelCardsTable.Relations[1].Target = tractordb.TractorsSchema()
	fuelPurchasesTable.Relations[0].Target = tractordb.TractorsSchema()
	fuelPurchasesTable.Relations[1].Target = workerdb.WorkersSchema()
	fuelPurchasesTable.Relations[2].Target = FuelCardsSchema()
	fuelPurchasesTable.Relations[3].Target = iftadb.JurisdictionsSchema()
	fuelPurchasesTable.Relations[4].Target = ImportBatchesSchema()
	importBatchesTable.Relations[0].Target = documentdb.DocumentsSchema()
	importBatchesTable.Relations[1].Target = FuelCardsSchema()
	importBatchesTable.Relations[2].Target = tenantdb.UsersSchema()
	importBatchesTable.Relations[3].Target = tenantdb.UsersSchema()
	importBatchesTable.Relations[4].Target = ImportRowsSchema()
	importRowsTable.Relations[0].Target = ImportBatchesSchema()
	importRowsTable.Relations[1].Target = FuelPurchasesSchema()
}

